 delta=dict(requirements=18,new_requirement_IDs=[],changed_requirement_records=[dict(index=i,id=r[i]['id'],fields={k:dict(before=oldr[i][k],after=r[i][k]) for k in r[i] if r[i][k]!=oldr[i][k]}) for i in range(18) if r[i]!=oldr[i]],unchanged_requirement_records=9,old_MPE_records_verbatim=27,shared_original_records_verbatim=83,Groove_R3_records_unchanged=34,Tuning_records_unchanged=32,new_case_ids=[c['id'] for c in new],current_MPE_cases=50,current_MPE_D12=39,current_MPE_U=11,logical_current_union=116,bounded_groups=13,actual_expected=None,actual_comparison=None,target='U',executed=False,complete_topics=0)
