def main():
 assert sys.dont_write_bytecode and sys.argv[1:] in (['--write'],['--check'])
 writing=sys.argv[1:]==['--write']
 if writing:assert not (P/'mpe-manifest-author-r3.json').exists(),'refuse write after seal'
